def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(5))  # 120

import threading
counter = 0

def increment():
    global counter
    for _ in range(100000):
        value = counter   # both threads may read the same value
        counter = value + 1

threads = [threading.Thread(target=increment) for _ in range(2)]
for t in threads: t.start()
for t in threads: t.join()
print(counter)  # may be less than 200000

